-- Configurable PWM generator: one counter, one comparator.
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;

entity pwm_gen is
    generic ( WIDTH : positive := 8 );
    port (
        clk     : in  std_logic;
        rst_n   : in  std_logic;                              -- active-low, synchronous
        duty    : in  unsigned(WIDTH-1 downto 0);
        pwm_out : out std_logic
    );
end entity;

architecture rtl of pwm_gen is
    signal count : unsigned(WIDTH-1 downto 0) := (others => '0');
    signal duty_r: unsigned(WIDTH-1 downto 0) := (others => '0');
begin
    process (clk)
    begin
        if rising_edge(clk) then
            if rst_n = '0' then
                count  <= (others => '0');
                duty_r <= (others => '0');
            else
                count <= count + 1;
                -- shadow register: duty changes only at the start of a period
                if count = 0 then
                    duty_r <= duty;
                end if;
            end if;
        end if;
    end process;

    pwm_out <= '1' when count < duty_r else '0';
end architecture;

// Configurable PWM generator: one counter, one comparator.
module pwm_gen #(parameter WIDTH = 8) (
    input  wire                  clk,
    input  wire                  rst_n,
    input  wire [WIDTH-1:0]      duty,
    output wire                  pwm_out
);
    reg [WIDTH-1:0] count  = 0;
    reg [WIDTH-1:0] duty_r = 0;

    always @(posedge clk) begin
        if (!rst_n) begin
            count  <= 0;
            duty_r <= 0;
        end else begin
            count <= count + 1'b1;
            if (count == 0) duty_r <= duty;   // shadow register
        end
    end

    assign pwm_out = (count < duty_r);
endmodule

-- Self-checking testbench for pwm_gen.
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;

entity tb_pwm_gen is end entity;

architecture sim of tb_pwm_gen is
    constant W       : positive := 8;
    constant PERIOD  : time := 10 ns;          -- 100 MHz
    constant STEPS   : positive := 2**W;       -- clock cycles per PWM period
    signal clk, rst_n, pwm : std_logic := '0';
    signal duty      : unsigned(W-1 downto 0) := (others => '0');
    signal stop_clk  : boolean := false;
begin
    -- 1. device under test
    dut : entity work.pwm_gen
        generic map (WIDTH => W)
        port map (clk => clk, rst_n => rst_n, duty => duty, pwm_out => pwm);

    -- 2. clock generation
    clk <= '0' when stop_clk else not clk after PERIOD/2;

    -- 3. stimulus and self-checking
    stim : process
        variable high : natural;
        -- measures the high time over one full period
        procedure measure(constant d : natural) is
        begin
            duty <= to_unsigned(d, W);
            wait for STEPS * PERIOD;           -- let the shadow register load
            high := 0;
            for i in 0 to STEPS - 1 loop
                wait until rising_edge(clk);
                if pwm = '1' then high := high + 1; end if;
            end loop;
            assert high = d
                report "duty " & integer'image(d) & " gave " & integer'image(high)
                severity error;
        end procedure;
    begin
        rst_n <= '0'; wait for 3 * PERIOD; rst_n <= '1';

        measure(0);        -- corner case: always low
        measure(1);        -- corner case: minimum pulse
        measure(128);      -- half
        measure(255);      -- corner case: maximum

        report "test finished" severity note;
        stop_clk <= true;
        wait;
    end process;
end architecture;
